import React, { useEffect, useState } from "react";

function MyAppointments() {
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem("token");

    if (!token) {
      alert("Please login first ❌");
      return;
    }

    fetch("http://localhost:8081/api/appointments/my", {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error("Failed to fetch appointments");
        }
        return res.json();
      })
      .then((data) => {
        setAppointments(data);
      })
      .catch((err) => {
        console.error(err);
        alert("Error fetching appointments ❌");
      });
  }, []);

  const cancelAppointment = (id) => {
    const token = localStorage.getItem("token");

    fetch(`http://localhost:8081/api/appointments/${id}/cancel`, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    })
      .then((res) => res.json())
      .then(() => {
        // update UI after cancel
        setAppointments((prev) =>
          prev.map((a) =>
            a.id === id ? { ...a, status: "CANCELLED" } : a
          )
        );
      })
      .catch((err) => console.error(err));
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>My Appointments</h2>

      {appointments.length === 0 ? (
        <p>No appointments found</p>
      ) : (
        appointments.map((a) => (
          <div
            key={a.id}
            style={{
              border: "1px solid #ccc",
              margin: "10px 0",
              padding: "10px",
              borderRadius: "8px",
            }}
          >
            <p><b>Doctor ID:</b> {a.doctor?.id}</p>
            <p><b>Date:</b> {a.appointmentDate}</p>
            <p><b>Time:</b> {a.timeSlot}</p>
            <p><b>Status:</b> {a.status}</p>

            {a.status === "BOOKED" && (
              <button
                onClick={() => cancelAppointment(a.id)}
                style={{
                  background: "red",
                  color: "#fff",
                  border: "none",
                  padding: "6px 10px",
                  borderRadius: "5px",
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>
            )}
          </div>
        ))
      )}
    </div>
  );
}

export default MyAppointments;
